import{_ as n,y as i,a as s,o as t,a6 as a,c as d,w as o,I as c,D as l,a7 as h}from"./chunks/framework.CJDy2q7X.js";const b=JSON.parse('{"title":"Order Fulfillment Actions (Admin)","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/workflows/admin/order-fulfillment-actions.md","filePath":"api/workflows/admin/order-fulfillment-actions.md","lastUpdated":1787725411000}'),u={name:"api/workflows/admin/order-fulfillment-actions.md"};function m(p,e,f,g,v,w){const r=i("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<h1 id="order-fulfillment-actions-admin" tabindex="-1">Order Fulfillment Actions (Admin) <a class="header-anchor" href="#order-fulfillment-actions-admin" aria-label="Permalink to &quot;Order Fulfillment Actions (Admin)&quot;">​</a></h1><p>Once an order exists it moves through a lifecycle — invoice, ship, refund, or cancel. Each action is a per-order endpoint under <code>/api/admin/orders/{id}/…</code> with its <strong>own eligibility guard</strong>: it refuses with a clear error when its prerequisite isn&#39;t met. This page is the theory; open each linked page for the exact body.</p><h2 id="agent-ask-inputs" tabindex="-1">Agent-ask inputs <a class="header-anchor" href="#agent-ask-inputs" aria-label="Permalink to &quot;Agent-ask inputs&quot;">​</a></h2><ul><li><strong>Integration token</strong> — ask the user; send as <code>Authorization: Bearer &lt;id&gt;|&lt;token&gt;</code>. Each action is gated by its permission (<code>sales.invoices.create</code>, <code>sales.shipments.create</code>, <code>sales.refunds.create</code>, <code>sales.orders.cancel</code>) — a role without it returns <code>403</code>.</li><li><strong>Server URL</strong> — ask the user for their Bagisto server&#39;s base URL (e.g. <code>https://store.example.com</code>) and prefix every endpoint path with it. Never assume localhost or a demo domain.</li></ul><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2>',5)),(t(),d(h,null,{default:o(()=>[l(r,{id:"mermaid-24",class:"mermaid",graph:"flowchart%20LR%0A%20%20order%5BOrder%20placed%5D%20--%3E%20inv%5BInvoice%3Cbr%2F%3Erecord%20payment%5D%0A%20%20inv%20--%3E%20ship%5BShip%3Cbr%2F%3Efulfil%20items%5D%0A%20%20ship%20--%3E%20refund%5BRefund%3Cbr%2F%3Eoptional%20return%5D%0A%20%20order%20-.-%3E%7Cnothing%20invoiced%2Fshipped%7C%20cancel%5BCancel%5D%0A%20%20order%20-.-%3E%7Cany%20time%7C%20comment%5BAdd%20comment%5D%0A"})]),fallback:o(()=>e[0]||(e[0]=[c(" Loading... ",-1)])),_:1})),e[2]||(e[2]=a('<p>A fulfilled order runs <strong>Invoice → Ship → (Refund)</strong>; an abandoned one runs <strong>Cancel</strong>. Comments work at any stage.</p><h2 id="the-actions-and-their-guards" tabindex="-1">The actions and their guards <a class="header-anchor" href="#the-actions-and-their-guards" aria-label="Permalink to &quot;The actions and their guards&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th><th>Guard (refuses when…)</th></tr></thead><tbody><tr><td><strong>Invoice</strong></td><td><a href="/api/rest-api/admin/sales/orders/create-invoice.html">POST invoices</a></td><td>closed / fraud / nothing left to invoice / <strong><code>paypal_standard</code></strong> (captured by the gateway, not the admin) / no permission</td></tr><tr><td><strong>Shipment</strong></td><td><a href="/api/rest-api/admin/sales/orders/create-shipment.html">POST shipments</a></td><td>closed / fraud / nothing left to ship / <strong>insufficient stock at the chosen inventory source</strong> / no permission</td></tr><tr><td><strong>Refund</strong></td><td><a href="/api/rest-api/admin/sales/orders/create-refund.html">POST refunds</a></td><td>closed / fraud / nothing left to refund / amount-zero / amount-exceeds-max / no permission</td></tr><tr><td><strong>Refund preview</strong></td><td><a href="/api/rest-api/admin/sales/orders/refund-preview.html">POST refunds/preview</a></td><td>same eligibility as refund, but <strong>never writes</strong> — returns the computed totals</td></tr><tr><td><strong>Cancel</strong></td><td><a href="/api/rest-api/admin/sales/orders/cancel.html">POST cancel</a></td><td>closed / fraud / nothing left to cancel (something already fully invoiced or shipped) / no permission</td></tr><tr><td><strong>Add comment</strong></td><td><a href="/api/rest-api/admin/sales/orders/add-comment.html">POST comments</a> · <a href="/api/rest-api/admin/sales/orders/list-comments.html">list</a></td><td>none — no permission gate</td></tr></tbody></table><h2 id="theory-gotchas" tabindex="-1">Theory &amp; gotchas <a class="header-anchor" href="#theory-gotchas" aria-label="Permalink to &quot;Theory &amp; gotchas&quot;">​</a></h2><ul><li><strong>Invoice records what&#39;s owed, not that it&#39;s paid.</strong> An invoice can be generated with no captured payment; the order/invoice stays <code>pending</code> until a payment transaction is recorded. <strong>Partial invoicing</strong> is allowed (invoice some SKUs now, the rest later) — each line is validated against its remaining <code>qty_to_invoice</code>.</li><li><strong><code>canCreateTransaction</code> on invoice-create</strong> (REST <code>can_create_transaction</code>, GraphQL <code>canCreateTransaction</code>, default false) auto-records a paid <code>order_transactions</code> row for the full invoice amount via the core listener — the &quot;Create Transaction&quot; checkbox on the admin invoice screen. Distinct from the standalone <a href="/api/rest-api/admin/sales/transactions/create.html">Record Payment</a> (<code>POST /api/admin/transactions</code>), which records a specific amount against an invoice.</li><li><strong>PayPal Standard orders can&#39;t be invoiced</strong> from the admin — the gateway captures asynchronously. The guard returns a distinct message.</li><li><strong>Shipment needs stock at the source.</strong> Beyond items-awaiting-shipment, the chosen inventory source must hold enough quantity; otherwise the per-SKU guard rejects. Partial shipments allowed.</li><li><strong>Always Refund-Preview first.</strong> <code>previewAdminRefund</code> computes subtotal/discount/tax/shipping/grand-total for the requested lines + adjustments without writing — drive the live &quot;Total Refund&quot; widget from it, then call create-refund. Refund needs an un-refunded invoiced amount (an order generally can&#39;t be refunded before it&#39;s invoiced).</li><li><strong>Cancel is early-abort only.</strong> Once anything is fully invoiced or shipped, cancel is refused — use refund instead.</li><li><strong>Comments email the customer</strong> when <code>customerNotified</code> is true (fires the core notification). No permission gate — matches the admin panel.</li><li><strong>Actions return the refreshed order.</strong> Cancel/invoice/etc. return the full order (same shape as <a href="/api/rest-api/admin/sales/orders/order-detail.html">order detail</a>) so the order-view screen refreshes without a follow-up GET. The generated invoice/shipment/refund also appears in its own store-wide menu (<a href="/api/rest-api/admin/sales/invoices/">Invoices</a> / <a href="/api/rest-api/admin/sales/shipments/">Shipments</a> / <a href="/api/rest-api/admin/sales/refunds/">Refunds</a>).</li></ul><h2 id="graphql-notes" tabindex="-1">GraphQL notes <a class="header-anchor" href="#graphql-notes" aria-label="Permalink to &quot;GraphQL notes&quot;">​</a></h2><p>Fields: <code>createAdminInvoice</code>, <code>createAdminShipment</code>, <code>createAdminRefund</code>, <code>previewAdminRefund</code>, <code>createAdminCancelOrder</code>, <code>createAdminOrderComment</code>. These are <strong>action / result mutations</strong> — select the documented result fields (the refreshed order, <code>success</code>, <code>message</code>), <strong>not</strong> a generic <code>id</code> (see the <a href="/api/workflows/admin/#graphql-the-must-know-rules">result-field rule</a>).</p><h2 id="status-codes-to-handle" tabindex="-1">Status codes to handle <a class="header-anchor" href="#status-codes-to-handle" aria-label="Permalink to &quot;Status codes to handle&quot;">​</a></h2><p>Every call below links to its <strong>REST</strong> endpoint page for concreteness. The sequence is transport-agnostic — the same flow works over GraphQL with the equivalent query or mutation, and each REST page cross-links to its GraphQL twin. Pick whichever transport your client uses; only the request shape changes, never the order of steps.</p><p><code>200/201</code> success · <code>401</code> unauthenticated · <code>403</code> permission · <code>404</code> order not found · <code>422</code> ineligible action / validation (per-SKU qty, refund amount, PayPal invoice).</p>',10))])}const _=n(u,[["render",m]]);export{b as __pageData,_ as default};
